window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e383ec61cd92f415"]={"versions": [{"id": "FIG-e383ec61cd92f415", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd Startup / Shutdown Activities</code>) im Kontext der AUTOSAR-Basissoftware (BSW). Das Diagramm stellt das Zusammenwirken zwischen dem ECU State Manager (<code>:EcuM</code>) und dem Watchdog Manager (<code>:WdgM</code>) während der Anlauf- und Abschaltphasen des Steuergeräts dar, einschließlich der Behandlung von Blockaden (Hangs) während der Initialisierung bzw. Deinitialisierung von BSW-Modulen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten (Lebenslinien):</p>\n<ul class=\"fig-list\"><li><code>:EcuM</code> (ECU State Manager)\n</li><li><code>:WdgM</code> (Watchdog Manager)\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\"><li>Interne Aktionen / Eigenaufrufe von <code>:EcuM</code>:\n<ul class=\"fig-list\"><li><code>Initialize / deinitialize module ref</code>\n</li><li><code>EcuM stuck in startup / shutdown process</code>\n</li></ul>\n</li><li>Synchroner Aufruf zwischen <code>:EcuM</code> und <code>:WdgM</code>:\n<ul class=\"fig-list\"><li><code>WdgM_UpdateAliveCounter(return,SEId)</code> mit Rückmeldeantwort (Return-Pfeil)\n</li></ul>\n</li><li>Externe Sequenz-Referenzen (<code>ref</code>), die auf <code>:WdgM</code>-Ebene ablaufen:\n<ul class=\"fig-list\"><li><code>Activation(Trigger)</code>\n</li><li><code>Activation(Do Not Trigger)</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf gliedert sich in zwei Hauptblöcke:</p>\n<ol class=\"fig-list\"><li>Reguläre Modulbehandlung (<code>loop [For some modules]</code>):\n</li></ol>\n<ul class=\"fig-list\"><li>Der <code>:EcuM</code> führt die Initialisierung bzw. Deinitialisierung eines Moduls aus (<code>Initialize / deinitialize module ref</code>).\n</li><li>Zeitgleich bzw. zyklisch läuft die Triggerung des Watchdogs über die Referenz <code>Activation(Trigger)</code>.\n</li><li>Der <code>:EcuM</code> ruft synchron <code>WdgM_UpdateAliveCounter(return,SEId)</code> am <code>:WdgM</code> auf, um die Alive-Überwachung für die Supervised Entity des Moduls zu bedienen, gefolgt von einer Bestätigung.\n</li></ul>\n<ol class=\"fig-list\"><li>Fehlerbehandlung bei Blockade (<code>opt</code>):\n</li></ol>\n<ul class=\"fig-list\"><li>Tritt eine Blockade auf (<code>EcuM stuck in startup / shutdown process</code>), wird kein weiterer Alive-Counter aktualisiert.\n</li><li>Erstes verschachteltes <code>loop [WdgMExpiredSupervisonCycleTol times]</code>: Während der tolerierten Anzahl an abgelaufenen Überwachungszyklen wird der Watchdog weiterhin über <code>Activation(Trigger)</code> getriggert.\n</li><li>Zweites nachfolgendes <code>loop [Until watchdog reset]</code>: Nach Ablauf der Toleranz schaltet das Verhalten um auf <code>Activation(Do Not Trigger)</code>, wodurch die Watchdog-Bedienung unterbleibt, bis der Hardware-Watchdog-Reset ausgelöst wird.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert das Alive-Supervision-Verhalten des Watchdog Managers während der Steuergeräte-Start- und Shutdown-Phasen:</p>\n<ul class=\"fig-list\"><li>Der EcuM muss für überwachte Module während Initialisierungs- und Deinitialisierungsschleifen <code>WdgM_UpdateAliveCounter</code> aufrufen.\n</li><li>Bleibt der EcuM stecken, detektiert der WdgM das Ausbleiben der Alive-Indikation.\n</li><li>Gemäß dem Konfigurationsparameter <code>WdgMExpiredSupervisionCycleTol</code> (im Diagramm als <code>WdgMExpiredSupervisonCycleTol</code> referenziert) toleriert der WdgM das Überschreiten für eine parametrierte Zyklenanzahl unter Beibehaltung der Triggerung, bevor die Watchdog-Triggerung eingestellt wird (<code>Do Not Trigger</code>) und der Hardware-Reset erzwungen wird.\n</li></ul>"}, {"id": "FIG-72030c890906985b", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd WdgM_Startup / Shutdown Activities</code>) im Kontext der AUTOSAR-Basissoftware (BSW). Das Diagramm stellt das Zusammenwirken zwischen dem ECU State Manager (<code>:EcuM</code>) und dem Watchdog Manager (<code>:WdgM</code>) während der Anlauf- und Abschaltphasen des Steuergeräts dar, einschließlich der Behandlung von Blockaden während der Initialisierung bzw. Deinitialisierung von BSW-Modulen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten (Lebenslinien):</p>\n<ul class=\"fig-list\"><li><code>:EcuM</code> (ECU State Manager)\n</li><li><code>:WdgM</code> (Watchdog Manager)\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\"><li>Interne Aktionen / Eigenaufrufe von <code>:EcuM</code>:\n<ul class=\"fig-list\"><li><code>Initialize / deinitialize module()</code>\n</li><li><code>EcuM stuck in startup / shutdown process()</code>\n</li></ul>\n</li><li>Synchroner Aufruf zwischen <code>:EcuM</code> und <code>:WdgM</code>:\n<ul class=\"fig-list\"><li><code>WdgM_UpdateAliveCounter(Std_ReturnType, WdgM_SupervisedEntityIdType)</code> mit Rückmeldeantwort (Return-Pfeil)\n</li></ul>\n</li><li>Externe Sequenz-Referenzen (<code>ref</code>), die auf <code>:WdgM</code>-Ebene ablaufen:\n<ul class=\"fig-list\"><li><code>Activation(Trigger)</code>\n</li><li><code>Activation(Do Not Trigger)</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf gliedert sich in zwei Hauptblöcke:</p>\n<ol class=\"fig-list\"><li>Reguläre Modulbehandlung (<code>loop [For some modules]</code>):\n</li></ol>\n<ul class=\"fig-list\"><li>Der <code>:EcuM</code> führt die Initialisierung bzw. Deinitialisierung eines Moduls aus (<code>Initialize / deinitialize module()</code>).\n</li><li>Parallel bzw. zyklisch läuft die Triggerung des Watchdogs über die Referenz <code>Activation(Trigger)</code>.\n</li><li>Der <code>:EcuM</code> bedient die Alive-Überwachung über den synchronen Funktionsaufruf <code>WdgM_UpdateAliveCounter(Std_ReturnType, WdgM_SupervisedEntityIdType)</code> am <code>:WdgM</code> mit anschließender Rückgabe.\n</li></ul>\n<ol class=\"fig-list\"><li>Fehlerbehandlung bei Blockade (<code>opt</code>):\n</li></ol>\n<ul class=\"fig-list\"><li>Tritt eine Blockade auf (<code>EcuM stuck in startup / shutdown process()</code>), unterbleibt das weitere Aufrufen von <code>WdgM_UpdateAliveCounter</code>.\n</li><li>Erstes verschachteltes <code>loop [WdgMExpiredSupervisonCycleTol times]</code>: Während der tolerierten Anzahl an Überwachungszyklen triggert der WdgM weiterhin über <code>Activation(Trigger)</code>.\n</li><li>Zweites nachfolgendes <code>loop [Until watchdog reset]</code>: Nach Erschöpfung der Toleranz wechselt das System zu <code>Activation(Do Not Trigger)</code>, wodurch keine Watchdog-Bedienung mehr erfolgt, bis der Watchdog-Reset greift.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert das Alive-Supervision-Verhalten des Watchdog Managers während der Steuergeräte-Start- und Shutdown-Phasen:</p>\n<ul class=\"fig-list\"><li>Der EcuM muss für überwachte Module während Initialisierungs- und Deinitialisierungsschleifen <code>WdgM_UpdateAliveCounter</code> aufrufen.\n</li><li>Bleibt der EcuM stecken, detektiert der WdgM das Ausbleiben der Alive-Indikation.\n</li><li>Gemäß dem Konfigurationsparameter <code>WdgMExpiredSupervisionCycleTol</code> (im Diagramm als <code>WdgMExpiredSupervisonCycleTol</code> referenziert) toleriert der WdgM das Überschreiten für eine parametrierte Zyklenanzahl unter Beibehaltung der Triggerung, bevor die Watchdog-Triggerung eingestellt wird (<code>Do Not Trigger</code>) und der Hardware-Reset erzwungen wird.\n</li></ul>"}], "trans": [{"from": "FIG-e383ec61cd92f415", "to": "FIG-72030c890906985b", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Diagrammkopf von <code>sd Startup / Shutdown Activities</code> in <code>sd WdgM_Startup / Shutdown Activities</code> umbenannt.\n</li><li>Signatur des Aufrufs von <code>WdgM_UpdateAliveCounter(return,SEId)</code> auf konkrete AUTOSAR-Standardtypen präzisiert: <code>WdgM_UpdateAliveCounter(Std_ReturnType, WdgM_SupervisedEntityIdType)</code>.\n</li><li>Interne EcuM-Aktivitäten formell mit Funktionsklammern versehen: <code>Initialize / deinitialize module()</code> statt <code>Initialize / deinitialize module ref</code> sowie <code>EcuM stuck in startup / shutdown process()</code> statt <code>EcuM stuck in startup / shutdown process</code>.\n</li></ul>"}]};
